def clasificar_carga(modalidad, accion):
    mapa = {
        ("texto", "generar"): "ia_generativa",
        ("texto", "clasificar"): "clasificacion_texto",
        ("texto", "extraer"): "extraccion_informacion",
        ("imagen", "analizar"): "vision_por_computadora",
        ("audio", "transcribir"): "voz_a_texto",
        ("mixto", "decidir"): "orquestacion_de_agentes",
    }
    return mapa.get((modalidad, accion), "desconocida")

escenarios = [
    ("texto", "generar"),
    ("imagen", "analizar"),
    ("audio", "transcribir"),
    ("texto", "extraer"),
    ("mixto", "decidir"),
]

for modalidad, accion in escenarios:
    print(f"{modalidad}/{accion} -> {clasificar_carga(modalidad, accion)}")
